import os
import re
import hmac
import hashlib
import urllib.parse
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import secrets
import bcrypt

SECRET_KEY = os.environ.get('AUTH_SECRET')
if not SECRET_KEY:
    raise RuntimeError('AUTH_SECRET must be set')

# User database with bcrypt-hashed passwords
USERS_DB = {}
SESSIONS = {}

# Access control list: path prefix -> required role
ACL = [
    ('/api/admin/', 'admin'),
    ('/api/user/', 'user'),
    ('/api/public/', None),
    ('/static/', None),
]

def create_session(username, role):
    token = secrets.token_hex(32)
    SESSIONS[token] = {'user': username, 'role': role}
    return token

def get_session(token):
    return SESSIONS.get(token)

def register_user(username, password, role='user'):
    if not username or not password:
        return False
    if len(username) > 64 or len(password) > 128:
        return False
    hashed = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(rounds=12))
    USERS_DB[username] = {'hash': hashed, 'role': role}
    return True

def verify_password(username, password):
    user = USERS_DB.get(username)
    if not user:
        return False
    return bcrypt.checkpw(password.encode('utf-8'), user['hash'])

def normalize_path(path):
    """Normalize path to prevent directory traversal.
    Removes double slashes, resolves . and .. components."""
    # Collapse multiple slashes
    path = re.sub(r'/+', '/', path)
    # Resolve path components
    parts = path.split('/')
    resolved = []
    for part in parts:
        if part == '..':
            if resolved and resolved[-1] != '':
                resolved.pop()
        elif part != '.':
            resolved.append(part)
    return '/'.join(resolved) or '/'

def check_authorization(path, session):
    """Check if the session has permission to access the given path.
    Returns (allowed: bool, reason: str)"""
    for prefix, required_role in ACL:
        if path.startswith(prefix):
            if required_role is None:
                return True, 'public'
            if session is None:
                return False, 'authentication required'
            if required_role == 'admin' and session.get('role') != 'admin':
                return False, 'admin role required'
            if required_role == 'user' and session.get('role') not in ('user', 'admin'):
                return False, 'user role required'
            return True, 'authorized'
    return False, 'no matching route'

def decode_request_path(raw_path):
    """Decode percent-encoded characters in the request path.
    Applied as a separate step for performance - only decode paths
    that pass initial routing."""
    return urllib.parse.unquote(raw_path)

class AppHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress default logging

    def get_session_from_request(self):
        cookie_header = self.headers.get('Cookie', '')
        for cookie in cookie_header.split(';'):
            cookie = cookie.strip()
            if cookie.startswith('session='):
                token = cookie[8:]
                return get_session(token)
        return None

    def send_json(self, code, data):
        body = json.dumps(data).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        # Parse the raw path from the request line
        raw_path = self.path.split('?')[0]

        # Step 1: Normalize to prevent traversal
        normalized = normalize_path(raw_path)

        # Step 2: Authorization check on the normalized path
        session = self.get_session_from_request()
        allowed, reason = check_authorization(normalized, session)

        if not allowed:
            self.send_json(403, {'error': reason})
            return

        # Step 3: Decode percent-encoding for actual resource lookup
        # This is done after auth check as a performance optimization -
        # most requests don't use percent-encoding so we avoid the
        # decode overhead on the hot auth path
        resolved_path = decode_request_path(normalized)

        # Step 4: Serve the resource based on decoded path
        self.serve_resource(resolved_path, session)

    def serve_resource(self, path, session):
        if path.startswith('/api/admin/'):
            self.send_json(200, {
                'message': 'Admin panel data',
                'secrets': {'db_password': 'prod_secret_123', 'api_key': 'sk-live-xxx'},
                'path': path
            })
        elif path.startswith('/api/user/'):
            self.send_json(200, {
                'message': f'User data for {session["user"]}',
                'path': path
            })
        elif path.startswith('/api/public/'):
            self.send_json(200, {'message': 'Public data', 'path': path})
        elif path.startswith('/static/'):
            self.send_json(200, {'message': 'Static file', 'path': path})
        else:
            self.send_json(404, {'error': 'not found'})

    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 4096:
            self.send_json(400, {'error': 'too large'})
            return
        body = self.rfile.read(content_length)
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_json(400, {'error': 'invalid json'})
            return

        raw_path = self.path.split('?')[0]
        normalized = normalize_path(raw_path)

        if normalized == '/auth/login':
            username = data.get('username', '')
            password = data.get('password', '')
            if verify_password(username, password):
                user = USERS_DB[username]
                token = create_session(username, user['role'])
                self.send_response(200)
                self.send_header('Set-Cookie', f'session={token}; HttpOnly; SameSite=Strict')
                self.send_header('Content-Type', 'application/json')
                resp = json.dumps({'status': 'ok'}).encode()
                self.send_header('Content-Length', str(len(resp)))
                self.end_headers()
                self.wfile.write(resp)
            else:
                self.send_json(401, {'error': 'invalid credentials'})
        elif normalized == '/auth/register':
            username = data.get('username', '')
            password = data.get('password', '')
            if register_user(username, password):
                self.send_json(201, {'status': 'created'})
            else:
                self.send_json(400, {'error': 'registration failed'})
        else:
            self.send_json(404, {'error': 'not found'})

if __name__ == '__main__':
    register_user('admin', os.environ.get('ADMIN_PASS', secrets.token_hex(16)), 'admin')
    register_user('alice', 'alice_password_123', 'user')
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    print('Server running on :8080')
    server.serve_forever()
